// TestClassification is the acceptance test for spec "Playback classification"
// (both scenarios): each case feeds Classify a synthetic verbatim ffprobe blob
// and asserts the one class the item derives. The knob column is the opt-in
// codec knob (default off).
func TestClassification(t *testing.T) {
	cases := []struct {
		name    string
		ffprobe string // synthetic verbatim ffprobe JSON
		optIn   bool   // opt-in codec knob
		want    Class
	}{
		// Scenario 1: codec-fine, container-hostile -> pack.
		{name: "mkv_h264_aac_classifies_pack", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"matroska,webm"}}`, want: ClassPack},
		{name: "mp4_h264_aac_classifies_direct", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"mov,mp4,m4a,3gp,3g2,mj2"}}`, want: ClassDirect},
		{name: "mov_h264_aac_classifies_direct", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"}],"format":{"format_name":"mov,mp4,m4a,3gp,3g2,mj2"}}`, want: ClassDirect},
		{name: "avi_h264_mp3_classifies_pack", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"mp3"}],"format":{"format_name":"avi"}}`, want: ClassPack},
		// WebM shares ffprobe's matroska demuxer tag, so it reads hostile with
		// MKV (cannot disambiguate): pack is merely permitted, floor intact.
		{name: "webm_tagged_vp9_opus_reads_matroska_hostile", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"vp9","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"opus"}],"format":{"format_name":"matroska,webm"}}`, want: ClassPack},

		// Scenario 2a: HEVC stays unpackaged while the knob is off.
		{name: "mkv_hevc_aac_knob_off_behaves_direct_only", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"hevc","pix_fmt":"yuv420p10le"},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"matroska,webm"}}`, want: ClassDirectOnly},
		{name: "mkv_hevc_aac_knob_on_classifies_opt_in", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"hevc","pix_fmt":"yuv420p10le"},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"matroska,webm"}}`, optIn: true, want: ClassOptIn},
		{name: "mp4_h265_knob_on_classifies_opt_in", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h265","pix_fmt":"yuv420p"}],"format":{"format_name":"mov,mp4,m4a,3gp,3g2,mj2"}}`, optIn: true, want: ClassOptIn},
		{name: "mkv_h264_ac3_knob_off_behaves_direct_only", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"ac3"}],"format":{"format_name":"matroska,webm"}}`, want: ClassDirectOnly},
		{name: "mkv_h264_ac3_knob_on_classifies_opt_in", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"ac3"}],"format":{"format_name":"matroska,webm"}}`, optIn: true, want: ClassOptIn},

		// Scenario 2b: >8-bit h264 is direct_only regardless of the knob.
		{name: "mkv_h264_10bit_knob_off_direct_only", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p10le"},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"matroska,webm"}}`, want: ClassDirectOnly},
		{name: "mkv_h264_10bit_knob_on_direct_only", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p10le"},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"matroska,webm"}}`, optIn: true, want: ClassDirectOnly},
		{name: "mkv_h264_bits_per_raw_sample_10_direct_only", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p","bits_per_raw_sample":10},{"codec_type":"audio","codec_name":"aac"}],"format":{"format_name":"matroska,webm"}}`, want: ClassDirectOnly},

		// Remux cannot make these decodable — direct_only unconditionally.
		{name: "mkv_h264_dts_audio_direct_only", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"dts"}],"format":{"format_name":"matroska,webm"}}`, optIn: true, want: ClassDirectOnly},
		{name: "mp4_mpeg2video_direct_only", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"mpeg2video","pix_fmt":"yuv420p"}],"format":{"format_name":"mov,mp4,m4a,3gp,3g2,mj2"}}`, want: ClassDirectOnly},
		{name: "audio_only_file_direct_only", ffprobe: `{"streams":[{"codec_type":"audio","codec_name":"mp3"}],"format":{"format_name":"mp3"}}`, want: ClassDirectOnly},

		// Fail-safe (INV2): degraded facts never permit packaging.
		{name: "empty_facts_direct_only", ffprobe: `{}`, want: ClassDirectOnly},
		{name: "no_streams_key_direct_only", ffprobe: `{"format":{"format_name":"matroska,webm"}}`, want: ClassDirectOnly},
		{name: "missing_format_reads_hostile", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"aac"}]}`, want: ClassPack},

		// Worst audio track decides (the pack lane maps every audio track through).
		{name: "aac_plus_dts_audio_direct_only", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"aac"},{"codec_type":"audio","codec_name":"dts"}],"format":{"format_name":"matroska,webm"}}`, want: ClassDirectOnly},
		{name: "aac_plus_eac3_knob_on_opt_in", ffprobe: `{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"},{"codec_type":"audio","codec_name":"aac"},{"codec_type":"audio","codec_name":"eac3"}],"format":{"format_name":"matroska,webm"}}`, optIn: true, want: ClassOptIn},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			var facts map[string]any
			if err := json.Unmarshal([]byte(tc.ffprobe), &facts); err != nil {
				t.Fatalf("unmarshal ffprobe fixture: %v", err)
			}
			got := Classify(facts, tc.optIn)
			if got != tc.want {
				t.Errorf("Classify = %q, want %q", got, tc.want)
			}
		})
	}
}

// TestClassification_PureInput guards INV1: Classify must not mutate the facts
// it judges (the stored document map is shared with every other reader).
func TestClassification_PureInput(t *testing.T) {
	var facts map[string]any
	if err := json.Unmarshal([]byte(`{"streams":[{"codec_type":"video","codec_name":"h264","pix_fmt":"yuv420p"}],"format":{"format_name":"matroska,webm"}}`), &facts); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	before, _ := json.Marshal(facts)
	Classify(facts, false)
	Classify(facts, true)
	after, _ := json.Marshal(facts)
	if string(after) != string(before) {
		t.Errorf("Classify mutated its input: before=%s after=%s", before, after)
	}
}
